/// <summary>
/// One classified auto-wrong line. The TSV column order is the property order of
/// <see cref="ToTsvRow"/>; <see cref="QualifierDiff"/> and <see cref="TierDirection"/> are stderr-only
/// detail for the <c>same-head-other-qualifier</c> and <c>row-choice-tier</c> relations.
/// </summary>
public sealed record ClassificationResult
{
	/// <summary>Holdout row id.</summary>
	public string HoldoutId { get; init; } = string.Empty;

	/// <summary>Line index within the recipe.</summary>
	public int LineIndex { get; init; }

	/// <summary>Trace set (<c>debug</c> or <c>batch</c>).</summary>
	public string Set { get; init; } = string.Empty;

	/// <summary>Relation of the accepted row to the key row (brief §4, first match wins).</summary>
	public string Relation { get; init; } = string.Empty;

	/// <summary>Decision site: <c>reuse</c>, <c>override</c>, <c>curated</c>, or <c>ranker</c>.</summary>
	public string Site { get; init; } = string.Empty;

	/// <summary>For <c>override</c> sites: <c>yes</c>/<c>no</c> — is the normalised rawText a key of <c>exact-overrides.json</c>; empty otherwise.</summary>
	public string OverrideKey { get; init; } = string.Empty;

	/// <summary>Accepted row's dataset tier.</summary>
	public string AcceptedTier { get; init; } = string.Empty;

	/// <summary>Key row's dataset tier.</summary>
	public string KeyTier { get; init; } = string.Empty;

	/// <summary>Accepted row's combined <c>FoodState</c> mask (state | satisfiers).</summary>
	public string AcceptedState { get; init; } = string.Empty;

	/// <summary>Key row's combined <c>FoodState</c> mask (state | satisfiers).</summary>
	public string KeyState { get; init; } = string.Empty;

	/// <summary>The atom's parsed name, verbatim.</summary>
	public string ParsedName { get; init; } = string.Empty;

	/// <summary>The key row's head phrase (head term plus non-state leading words), singularised, space-joined.</summary>
	public string KeyHead { get; init; } = string.Empty;

	/// <summary>Accepted row description.</summary>
	public string AcceptedDesc { get; init; } = string.Empty;

	/// <summary>Key row description.</summary>
	public string KeyDesc { get; init; } = string.Empty;

	/// <summary>The raw recipe line.</summary>
	public string RawText { get; init; } = string.Empty;

	/// <summary>Trace field a relation step needed but the trace did not carry (drives the <c>other</c> relation); empty when none.</summary>
	public string MissingField { get; init; } = string.Empty;

	/// <summary>For <c>same-head-other-qualifier</c>: the qualifier words each side carries that the other does not.</summary>
	public string QualifierDiff { get; init; } = string.Empty;

	/// <summary>For <c>row-choice-tier</c>: which tier is higher, <c>key</c> or <c>accepted</c>.</summary>
	public string TierDirection { get; init; } = string.Empty;

	/// <summary>
	/// The TSV row in the brief's column order:
	/// <c>holdoutId lineIndex set relation site overrideKey acceptedTier keyTier acceptedState keyState parsedName keyHead acceptedDesc keyDesc rawText</c>.
	/// </summary>
	/// <returns>The tab-joined row, with tabs/newlines in text fields flattened to spaces.</returns>
	public string ToTsvRow()
	{
		string Cell(string value) => value.Replace('\t', ' ').Replace('\n', ' ').Replace('\r', ' ');

		return string.Join('\t',
			Cell(HoldoutId),
			LineIndex.ToString(System.Globalization.CultureInfo.InvariantCulture),
			Cell(Set),
			Cell(Relation),
			Cell(Site),
			Cell(OverrideKey),
			Cell(AcceptedTier),
			Cell(KeyTier),
			Cell(AcceptedState),
			Cell(KeyState),
			Cell(ParsedName),
			Cell(KeyHead),
			Cell(AcceptedDesc),
			Cell(KeyDesc),
			Cell(RawText));
	}
}
