{"content":"using System.Text.RegularExpressions;

using LetUsCook.AutoWrongCensus.Models;
using LetUsCook.Fdc;
using LetUsCook.Fdc.Lexicon;
using LetUsCook.Fdc.Matching;
using LetUsCook.Fdc.Parsing;
using LetUsCook.Fdc.Resolver;

namespace LetUsCook.AutoWrongCensus.Services;

/// <summary>
/// Classifies one auto-wrong trace line on two axes — relation (accepted row vs key row) and site
/// (where the line was accepted) — using the production helpers only (D-014):
/// <see cref="FdcNormalizer.NormalizeToTokens"/>, <see cref="FdcMatcher.ExtractCandidateState"/>,
/// <see cref="FdcMatcher.ExtractCandidateSatisfiers"/>, <see cref="FdcDescriptionParser.Parse"/>,
/// <see cref="IngredientLineResolver.SingularizeToken"/> and <see cref="IngredientLineResolver.ShouldReuse"/>.
/// </summary>
public sealed partial class AutoWrongClassifier
{
	/// <summary>Relation: the key row is empty.</summary>
	public const string NoLabel = "no-label";

	/// <summary>Relation: a can/jar unit in the raw text, the key row is Canned, the accepted row is not.</summary>
	public const string PackUnitState = "pack-unit-state";

	/// <summary>Relation: the key head phrase has two or more words and the parsed name is only its first word.</summary>
	public const string CompoundHeadLost = "compound-head-lost";

	/// <summary>Relation: the head terms agree and the state masks differ.</summary>
	public const string StateMismatch = "state-mismatch";

	/// <summary>Relation: head and state agree and the dataset tier differs.</summary>
	public const string RowChoiceTier = "row-choice-tier";

	/// <summary>Relation: head, state and tier agree; only the qualifiers differ.</summary>
	public const string SameHeadOtherQualifier = "same-head-other-qualifier";

	/// <summary>Relation: the head terms differ.</summary>
	public const string SiblingFood = "sibling-food";

	/// <summary>Relation: nothing above holds, or a field a check needed was missing.</summary>
	public const string Other = "other";

	/// <summary>Site: the line reused an existing row via the ranker path.</summary>
	public const string SiteReuse = "reuse";

	/// <summary>Site: the exact-override path.</summary>
	public const string SiteOverride = "override";

	/// <summary>Site: the curated catalogue path.</summary>
	public const string SiteCurated = "curated";

	/// <summary>Site: the ranker path without reuse.</summary>
	public const string SiteRanker = "ranker";

	private readonly FdcNormalizer _normalizer;
	private readonly ExactOverrideKeyIndex _overrideKeys;

	// Reused single-token list for the per-token state checks: ExtractCandidateState/
	// ExtractCandidateSatisfiers take IReadOnlyList, and the runner is single-threaded.
	private readonly List<string> _singleToken = [];

	/// <summary>Creates the classifier over the production normalizer and the override key set.</summary>
	/// <param name="normalizer">The production FDC normalizer.</param>
	/// <param name="overrideKeys">The <c>exact-overrides.json</c> key set.</param>
	public AutoWrongClassifier(FdcNormalizer normalizer, ExactOverrideKeyIndex overrideKeys)
	{
		_normalizer = normalizer ?? throw new ArgumentNullException(nameof(normalizer));
		_overrideKeys = overrideKeys ?? throw new ArgumentNullException(nameof(overrideKeys));
	}

	[GeneratedRegex(@"\b(?:cans?|jars?)\b", RegexOptions.IgnoreCase)]
	private static partial Regex PackUnitRegex();

	/// <summary>
	/// Classifies one auto-wrong line. The first relation that holds wins (brief §4 order 1–8);
	/// a relation that needs a field the trace lacks yields <see cref="Other"/> with
	/// <see cref="ClassificationResult.MissingField"/> naming it.
	/// </summary>
	/// <param name="line">The trace line (<c>auto == true &amp;&amp; correct == false</c>).</param>
	/// <returns>The classification; <see cref="ClassificationResult.Site"/> is empty when the atom path is unknown.</returns>
	public ClassificationResult Classify(TraceLine line)
	{
		ArgumentNullException.ThrowIfNull(line);

		var atom = line.Atoms.FirstOrDefault(a => a.Outcome == "accepted") ?? line.Atoms.FirstOrDefault();
		var keyDesc = line.ExpectedDescriptions.FirstOrDefault() ?? string.Empty;
		var acceptedDesc = line.ActualDescriptions.FirstOrDefault() ?? string.Empty;
		var keyTier = line.ExpectedDataTypes.FirstOrDefault() ?? string.Empty;
		var acceptedTier = line.ActualDataTypes.FirstOrDefault() ?? string.Empty;

		var (site, overrideKey) = ClassifySite(atom, line.RawText);

		var keyTokens = _normalizer.NormalizeToTokens(keyDesc);
		var acceptedTokens = _normalizer.NormalizeToTokens(acceptedDesc);
		var keyState = CombinedState(keyTokens);
		var acceptedState = CombinedState(acceptedTokens);

		var keyHead = SingularPhrase(FdcDescriptionParser.Parse(keyDesc, DatasetOf(keyTier)).HeadTerm);
		var acceptedHead = SingularPhrase(FdcDescriptionParser.Parse(acceptedDesc, DatasetOf(acceptedTier)).HeadTerm);
		var parsedName = SingularPhrase(atom?.ParsedName ?? string.Empty);
		var keyHeadPhrase = KeyHeadPhrase(keyTokens);

		string relation;
		string? missingField = null;
		IReadOnlyList<string>? keyOnlyQualifiers = null;
		IReadOnlyList<string>? acceptedOnlyQualifiers = null;

		if (string.IsNullOrWhiteSpace(keyDesc))
		{
			relation = NoLabel;
		}
		else if (PackUnitRegex().IsMatch(line.RawText) && (keyState & FoodState.Canned) != FoodState.None && (acceptedState & FoodState.Canned) == FoodState.None)
		{
			relation = PackUnitState;
		}
		else if (keyHeadPhrase.Count >= 2 && parsedName.Count == 1 &&
			string.Equals(parsedName[0], IngredientLineResolver.SingularizeToken(keyHeadPhrase[0]), StringComparison.OrdinalIgnoreCase))
		{
			relation = CompoundHeadLost;
		}
		else if (keyHead.SequenceEqual(acceptedHead, StringComparer.OrdinalIgnoreCase))
		{
			if (keyState != acceptedState)
			{
				relation = StateMismatch;
			}
			else if (string.IsNullOrWhiteSpace(keyTier) || string.IsNullOrWhiteSpace(acceptedTier))
			{
				relation = Other;
				missingField = string.IsNullOrWhiteSpace(acceptedTier) ? "actualDataTypes" : "expectedDataTypes";
			}
			else if (!string.Equals(keyTier, acceptedTier, StringComparison.OrdinalIgnoreCase))
			{
				relation = RowChoiceTier;
			}
			else
			{
				relation = SameHeadOtherQualifier;
				var keyQualifiers = SingularPhraseList(FdcDescriptionParser.Parse(keyDesc, DatasetOf(keyTier)).Qualifiers);
				var acceptedQualifiers = SingularPhraseList(FdcDescriptionParser.Parse(acceptedDesc, DatasetOf(acceptedTier)).Qualifiers);
				keyOnlyQualifiers = keyQualifiers.Except(acceptedQualifiers, StringComparer.OrdinalIgnoreCase).OrderBy(t => t, StringComparer.OrdinalIgnoreCase).ToArray();
				acceptedOnlyQualifiers = acceptedQualifiers.Except(keyQualifiers, StringComparer.OrdinalIgnoreCase).OrderBy(t => t, StringComparer.OrdinalIgnoreCase).ToArray();
			}
		}
		else
		{
			relation = SiblingFood;
		}

		return new ClassificationResult
		{
			HoldoutId = line.HoldoutId,
			LineIndex = line.LineIndex,
			Set = line.Set,
			Relation = relation,
			Site = site,
			OverrideKey = overrideKey,
			AcceptedTier = acceptedTier,
			KeyTier = keyTier,
			AcceptedState = acceptedState.ToString(),
			KeyState = keyState.ToString(),
			ParsedName = atom?.ParsedName ?? string.Empty,
			KeyHead = string.Join(' ', keyHeadPhrase),
			AcceptedDesc = acceptedDesc,
			KeyDesc = keyDesc,
			RawText = line.RawText,
			MissingField = missingField,
			KeyOnlyQualifiers = keyOnlyQualifiers,
			AcceptedOnlyQualifiers = acceptedOnlyQualifiers,
		};
	}

	/// <summary>
	/// The key head phrase: the key description's normalized tokens up to (excluding) the first token
	/// production treats as a state or modifier word — <see cref="FdcLexicon.ModifierWords"/> or a
	/// non-<see cref="FoodState.None"/> result from <see cref="FdcMatcher.ExtractCandidateState"/> /
	/// <see cref="FdcMatcher.ExtractCandidateSatisfiers"/> on the token alone. "Bread, crumbs, dry,
	/// grated, plain" → <c>bread crumbs</c>; "Nuts, almonds, blanched" → <c>nut almond</c>.
	/// </summary>
	/// <param name="keyTokens">The key description's normalized tokens.</param>
	/// <returns>The head phrase tokens.</returns>
	public IReadOnlyList<string> KeyHeadPhrase(IReadOnlyList<string> keyTokens)
	{
		var phrase = new List<string>();
		foreach (var token in keyTokens)
		{
			if (IsStateOrModifierWord(token))
			{
				break;
			}

			phrase.Add(token);
		}

		return phrase;
	}

	/// <summary>
	/// The production state mask for a token list: <see cref="FdcMatcher.ExtractCandidateState"/> ∪
	/// <see cref="FdcMatcher.ExtractCandidateSatisfiers"/> — the same composition the matcher feeds
	/// <c>StateAgrees</c> (FdcMatcher.cs:1155–1157).
	/// </summary>
	/// <param name="tokens">The normalized tokens.</param>
	/// <returns>The combined mask.</returns>
	public static FoodState CombinedState(IReadOnlyList<string> tokens) =>
		FdcMatcher.ExtractCandidateState(tokens) | FdcMatcher.ExtractCandidateSatisfiers(tokens);

	/// <summary>
	/// The resolver's own exact-phrase reuse rule applied to the line's parsed name and the linked
	/// master slug — the census statistic for <c>reuse</c>-site lines (D-014: the production rule,
	/// not a copy).
	/// </summary>
	/// <param name="parsedName">The atom's parsed name.</param>
	/// <param name="linkedIngredientId">The linked master slug, or null when none was linked.</param>
	/// <returns>Whether the production rule would reuse the linked master for this name; null when unlinked.</returns>
	public static bool? ShouldReuseLinkedMaster(string parsedName, string? linkedIngredientId)
	{
		if (string.IsNullOrWhiteSpace(linkedIngredientId))
		{
			return null;
		}

		var slug = IngredientLineParser.ComputeSlug(parsedName);
		return slug.Length > 0 && IngredientLineResolver.ShouldReuse(slug, linkedIngredientId);
	}

	private (string Site, string OverrideKey) ClassifySite(TraceAtom? atom, string rawText)
	{
		if (atom is null)
		{
			return (string.Empty, string.Empty);
		}

		return atom.Path.ToLowerInvariant() switch
		{
			"override" => (SiteOverride, _overrideKeys.IsKey(NormalizeForOverrideKey(rawText)) ? "yes" : "no"),
			"curated" => (SiteCurated, string.Empty),
			"ranker" => (atom.Reused ? SiteReuse : SiteRanker, string.Empty),
			_ => (string.Empty, string.Empty),
		};
	}

	/// <summary>
	/// Folds a raw line for the <c>exact-overrides.json</c> key lookup: lower-cased, trimmed, and
	/// content from the first <c>(</c> dropped — the same fold <c>FdcMatcher.MatchAsync</c> applies
	/// before its raw-key lookup (FdcMatcher.cs:165, <c>StripFromParenthesis</c> is private there).
	/// </summary>
	/// <param name="rawText">The raw line text.</param>
	/// <returns>The folded lookup key.</returns>
	public static string NormalizeForOverrideKey(string rawText)
	{
		var lowered = rawText.Trim().ToLowerInvariant();
		var paren = lowered.IndexOf('(', StringComparison.Ordinal);
		return (paren >= 0 ? lowered[..paren] : lowered).Trim();
	}

	private static FdcDataset DatasetOf(string tier) =>
		Enum.TryParse<FdcDataset>(tier, ignoreCase: true, out var dataset) ? dataset : FdcDataset.None;

	private bool IsStateOrModifierWord(string token)
	{
		if (FdcLexicon.Default.ModifierWords.Contains(token))
		{
			return true;
		}

		_singleToken.Clear();
		_singleToken.Add(token);
		return FdcMatcher.ExtractCandidateState(_singleToken) != FoodState.None
			|| FdcMatcher.ExtractCandidateSatisfiers(_singleToken) != FoodState.None;
	}

	private IReadOnlyList<string> SingularPhrase(string? text) =>
		_normalizer.NormalizeToTokens(text).Select(IngredientLineResolver.SingularizeToken).ToArray();

	private IReadOnlyList<string> SingularPhraseList(IReadOnlyList<string> tokens) =>
		tokens.Select(IngredientLineResolver.SingularizeToken).ToArray();
}
