{"content":"using System.Text.Json;

using LetUsCook.AutoWrongCensus.Models;
using LetUsCook.AutoWrongCensus.Options;
using LetUsCook.Fdc.Lexicon;
using LetUsCook.Fdc.Resolver;
using Microsoft.Extensions.Options;

namespace LetUsCook.AutoWrongCensus.Services;

/// <summary>
/// The census runner: reads one HoldoutGate trace JSONL, refuses any set other than <c>debug</c> or
/// <c>batch</c> (D-029), classifies every <c>auto &amp;&amp; !correct</c> line through
/// <see cref="AutoWrongClassifier"/> and writes the TSV to <see cref="OutputWriters.Output"/> with
/// the relation × site summary on <see cref="OutputWriters.Error"/>.
/// </summary>
public sealed class AutoWrongCensusRunner(
	IOptions<AutoWrongCensusOptions> options,
	AutoWrongClassifier classifier,
	FdcNormalizer normalizer,
	OutputWriters writers) : IAutoWrongCensusRunner
{
	private static readonly JsonSerializerOptions JsonOptions = new(JsonSerializerDefaults.Web);

	private const string CensusHeader =
		"holdoutId\tlineIndex\tset\trelation\tsite\toverrideKey\tacceptedTier\tkeyTier\tacceptedState\tkeyState\tparsedName\tkeyHead\tacceptedDesc\tkeyDesc\trawText";

	private const string PairsHeader = "holdoutId\tlineIndex\tparsedNameHead\tkeyHead\trawText";

	/// <inheritdoc />
	public async Task<int> RunAsync(CancellationToken cancellationToken)
	{
		var opts = options.Value;
		if (string.IsNullOrEmpty(opts.Command))
		{
			writers.Error.WriteLine("unusable arguments; expected: census <trace.jsonl> | pairs <census.tsv> <trace.jsonl>");
			return 1;
		}

		if (!File.Exists(opts.TracePath))
		{
			writers.Error.WriteLine($"trace file not found: {opts.TracePath}");
			return 1;
		}

		var lines = await ReadTraceAsync(opts.TracePath, cancellationToken).ConfigureAwait(false);
		if (lines is null)
		{
			return 1;
		}

		var refused = lines.Select(l => l.Set).Distinct(StringComparer.Ordinal).FirstOrDefault(s => s is not ("debug" or "batch"));
		if (refused is not null)
		{
			writers.Error.WriteLine($"refused: trace set '{refused}' is not debug or batch (D-029: no sealed read)");
			return 1;
		}

		return opts.Command.Equals(CommandLineArgumentParser.CensusCommand, StringComparison.OrdinalIgnoreCase)
			? RunCensus(lines)
			: await RunPairsAsync(opts, lines, cancellationToken).ConfigureAwait(false);
	}

	private async Task<IReadOnlyList<TraceLine>?> ReadTraceAsync(string path, CancellationToken cancellationToken)
	{
		var lines = new List<TraceLine>();
		try
		{
			await foreach (var raw in File.ReadLinesAsync(path, cancellationToken).ConfigureAwait(false))
			{
				if (string.IsNullOrWhiteSpace(raw))
				{
					continue;
				}

				lines.Add(JsonSerializer.Deserialize<TraceLine>(raw, JsonOptions)
					?? throw new InvalidOperationException($"trace line at {path} deserialized to null"));
			}
		}
		catch (Exception ex) when (ex is JsonException or IOException)
		{
			writers.Error.WriteLine($"cannot read trace {path}: {ex.Message}");
			return null;
		}

		return lines;
	}

	private int RunCensus(IReadOnlyList<TraceLine> lines)
	{
		var autoWrong = lines.Where(l => l.Auto && !l.Correct).ToList();
		var results = new List<ClassificationResult>(autoWrong.Count);

		foreach (var line in autoWrong)
		{
			ClassificationResult result;
			try
			{
				result = classifier.Classify(line);
			}
			catch (InvalidOperationException ex)
			{
				writers.Error.WriteLine(ex.Message);
				return 1;
			}

			if (string.IsNullOrEmpty(result.Site))
			{
				writers.Error.WriteLine($"unknown atom path '{line.Atoms.FirstOrDefault()?.Path}' at {line.HoldoutId}#{line.LineIndex}; refusing to guess a site");
				return 1;
			}

			results.Add(result);
		}

		writers.Output.WriteLine(CensusHeader);
		foreach (var r in results)
		{
			writers.Output.WriteLine(string.Join('\t',
				Sanitize(r.HoldoutId), r.LineIndex, Sanitize(r.Set), Sanitize(r.Relation), Sanitize(r.Site), Sanitize(r.OverrideKey),
				Sanitize(r.AcceptedTier), Sanitize(r.KeyTier), Sanitize(r.AcceptedState), Sanitize(r.KeyState),
				Sanitize(r.ParsedName), Sanitize(r.KeyHead), Sanitize(r.AcceptedDesc), Sanitize(r.KeyDesc), Sanitize(r.RawText)));
		}

		WriteSummary(results);
		return 0;
	}

	private void WriteSummary(IReadOnlyList<ClassificationResult> results)
	{
		var set = results.Count > 0 ? results[0].Set : string.Empty;
		writers.Error.WriteLine($"autoWrongCensus set={set} autoWrongLines={results.Count}");

		foreach (var group in results.GroupBy(r => (r.Relation, r.Site)).OrderBy(g => g.Key.Relation).ThenBy(g => g.Key.Site))
		{
			writers.Error.WriteLine($"{group.Key.Relation}\t{group.Key.Site}\t{group.Count()}");
		}

		var otherCount = results.Count(r => r.Relation == AutoWrongClassifier.RelationOther);
		writers.Error.WriteLine($"other={otherCount}/{results.Count} ({(results.Count > 0 ? otherCount * 100.0 / results.Count : 0.0):F1}%)");

		var missing = results.Where(r => r.MissingField is not null).GroupBy(r => r.MissingField!).OrderBy(g => g.Key);
		foreach (var group in missing)
		{
			writers.Error.WriteLine($"missingField {group.Key}={group.Count()}");
		}

		var overrideLines = results.Where(r => r.Site == AutoWrongClassifier.SiteOverride).ToList();
		if (overrideLines.Count > 0)
		{
			writers.Error.WriteLine($"overrideKey yes={overrideLines.Count(r => r.OverrideKey == "yes")} no={overrideLines.Count(r => r.OverrideKey == "no")}");
		}

		var reuseLines = results.Where(r => r.Site == AutoWrongClassifier.SiteReuse).ToList();
		if (reuseLines.Count > 0)
		{
			var checkedCount = 0;
			var shouldReuseFalse = 0;
			foreach (var r in reuseLines)
			{
				var line = FindLine(r);
				var atom = line?.Atoms.FirstOrDefault(a => a.Outcome.Equals("accepted", StringComparison.OrdinalIgnoreCase)) ?? line?.Atoms.FirstOrDefault();
				if (line is null || atom is null || string.IsNullOrEmpty(atom.LinkedIngredientId))
				{
					continue;
				}

				checkedCount++;
				if (!IngredientLineResolver.ShouldReuse(IngredientLineParser.ComputeSlug(atom.ParsedName), atom.LinkedIngredientId))
				{
					shouldReuseFalse++;
				}
			}

			writers.Error.WriteLine($"reuse lines where ShouldReuse(parsedName, linkedIngredientId) is false: {shouldReuseFalse}/{checkedCount}");
		}

		var tierLines = results.Where(r => r.Relation == AutoWrongClassifier.RelationRowChoiceTier).ToList();
		if (tierLines.Count > 0)
		{
			writers.Error.WriteLine($"row-choice-tier key higher={tierLines.Count(r => TierRank(r.KeyTier) > TierRank(r.AcceptedTier))} accepted higher={tierLines.Count(r => TierRank(r.AcceptedTier) > TierRank(r.KeyTier))}");
		}

		foreach (var r in results.Where(r => r.Relation == AutoWrongClassifier.RelationSameHeadOtherQualifier))
		{
			writers.Error.WriteLine($"qualdiff {r.HoldoutId}#{r.LineIndex} keyOnly=[{string.Join(' ', r.KeyOnlyQualifiers ?? [])}] acceptedOnly=[{string.Join(' ', r.AcceptedOnlyQualifiers ?? [])}]");
		}
	}

	private TraceLine? _lastLine;

	private TraceLine? FindLine(ClassificationResult r) => _lastLine;

	private static int TierRank(string tier) => tier.ToLowerInvariant() switch
	{
		"foundation" => 4,
		"srlegacy" => 3,
		"survey" => 2,
		"branded" => 1,
		_ => 0,
	};

	private static string Sanitize(string value) => value.Replace('\t', ' ').Replace('\n', ' ').Replace('\r', ' ');

	private async Task<int> RunPairsAsync(AutoWrongCensusOptions opts, IReadOnlyList<TraceLine> lines, CancellationToken cancellationToken)
	{
		if (!File.Exists(opts.CensusTsvPath))
		{
			writers.Error.WriteLine($"census tsv not found: {opts.CensusTsvPath}");
			return 1;
		}

		var wanted = new HashSet<(string HoldoutId, int LineIndex)>();
		try
		{
			var allLines = await File.ReadLinesAsync(opts.CensusTsvPath, cancellationToken).ToListAsync(cancellationToken).ConfigureAwait(false);
			if (allLines.Count == 0)
			{
				writers.Error.WriteLine($"census tsv {opts.CensusTsvPath} is empty");
				return 1;
			}

			var header = allLines[0].Split('\t');
			var idCol = Array.IndexOf(header, "holdoutId");
			var idxCol = Array.IndexOf(header, "lineIndex");
			var blockerCol = Array.IndexOf(header, "blocker");
			var routeCol = Array.IndexOf(header, "route");
			if (idCol < 0 || idxCol < 0 || blockerCol < 0 || routeCol < 0)
			{
				writers.Error.WriteLine($"census tsv {opts.CensusTsvPath} is missing a required column (holdoutId/lineIndex/blocker/route)");
				return 1;
			}

			foreach (var raw in allLines.Skip(1))
			{
				if (string.IsNullOrWhiteSpace(raw))
				{
					continue;
				}

				var cells = raw.Split('\t');
				if (cells.Length <= Math.Max(idxCol, Math.Max(blockerCol, routeCol))
					|| !cells[blockerCol].Equals("window", StringComparison.Ordinal)
					|| !cells[routeCol].Equals("compound", StringComparison.Ordinal)
					&& !cells[routeCol].Equals("other", StringComparison.Ordinal))
				{
					continue;
				}

				if (int.TryParse(cells[idxCol], out var lineIndex))
				{
					wanted.Add((cells[idCol], lineIndex));
				}
			}
		}
		catch (IOException ex)
		{
			writers.Error.WriteLine($"cannot read census tsv {opts.CensusTsvPath}: {ex.Message}");
			return 1;
		}

		var byKey = lines.ToDictionary(l => (l.HoldoutId, l.LineIndex));
		writers.Output.WriteLine(PairsHeader);
		var emitted = 0;
		var missing = 0;
		foreach (var (holdoutId, lineIndex) in wanted)
		{
			if (!byKey.TryGetValue((holdoutId, lineIndex), out var line))
			{
				missing++;
				continue;
			}

			var atom = line.Atoms.FirstOrDefault(a => a.Outcome.Equals("accepted", StringComparison.OrdinalIgnoreCase)) ?? line.Atoms.FirstOrDefault();
			var parsedNameHead = string.Join(' ', atom is null
				? []
				: Array.ConvertAll(normalizer.NormalizeToTokens(atom.ParsedName).ToArray(), t => IngredientLineResolver.SingularizeToken(t)));
			var keyDesc = line.ExpectedDescriptions.Count > 0 ? line.ExpectedDescriptions[0] : string.Empty;
			var keyHead = string.Join(' ', classifier.KeyHeadPhrase(normalizer.NormalizeToTokens(keyDesc)));
			writers.Output.WriteLine(string.Join('\t', Sanitize(holdoutId), lineIndex, Sanitize(parsedNameHead), Sanitize(keyHead), Sanitize(line.RawText)));
			emitted++;
		}

		writers.Error.WriteLine($"pairs wanted={wanted.Count} emitted={emitted} missingInTrace={missing}");
		return 0;
	}
